import java.util.*;

public class CrackEquation {
    static final String CHARS = "01+-*()=";
    static int count = 0;
    static String encrypted;
    static List<Character> letters;
    static Map<Character, Character> assignment;
    static boolean[] used;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        encrypted = sc.nextLine().trim();
        sc.close();

        // Collect distinct letters
        Set<Character> letterSet = new HashSet<>();
        for (char c : encrypted.toCharArray()) {
            if (c >= 'A' && c <= 'Z') {
                letterSet.add(c);
            }
        }
        letters = new ArrayList<>(letterSet);
        int n = letters.size();

        // If no letters, just check the string directly
        if (n == 0) {
            if (isValid(encrypted)) {
                System.out.println(1);
            } else {
                System.out.println(0);
            }
            return;
        }

        assignment = new HashMap<>();
        used = new boolean[CHARS.length()];
        backtrack(0);
        System.out.println(count);
    }

    static void backtrack(int idx) {
        if (idx == letters.size()) {
            // Build substituted string
            StringBuilder sb = new StringBuilder();
            for (char c : encrypted.toCharArray()) {
                if (c >= 'A' && c <= 'Z') {
                    sb.append(assignment.get(c));
                } else {
                    sb.append(c);
                }
            }
            if (isValid(sb.toString())) {
                count++;
            }
            return;
        }

        char letter = letters.get(idx);
        for (int i = 0; i < CHARS.length(); i++) {
            if (!used[i]) {
                used[i] = true;
                assignment.put(letter, CHARS.charAt(i));
                backtrack(idx + 1);
                used[i] = false;
            }
        }
    }

    static boolean isValid(String expr) {
        // Split by '='
        int eqPos = expr.indexOf('=');
        if (eqPos == -1) return false;
        String left = expr.substring(0, eqPos);
        String right = expr.substring(eqPos + 1);

        try {
            int leftVal = evaluate(left);
            int rightVal = evaluate(right);
            return leftVal == rightVal;
        } catch (Exception e) {
            return false;
        }
    }

    static int evaluate(String expr) {
        // Remove spaces just in case
        expr = expr.trim();
        if (expr.isEmpty()) throw new RuntimeException("Empty expression");

        // Use a stack for infix evaluation with +, -, *, and parentheses
        // We'll convert to postfix and evaluate
        return evalPostfix(infixToPostfix(expr));
    }

    static String infixToPostfix(String expr) {
        StringBuilder output = new StringBuilder();
        Stack<Character> ops = new Stack<>();
        for (int i = 0; i < expr.length(); i++) {
            char c = expr.charAt(i);
            if (c == '0' || c == '1') {
                output.append(c);
            } else if (c == '(') {
                ops.push(c);
            } else if (c == ')') {
                while (!ops.isEmpty() && ops.peek() != '(') {
                    output.append(ops.pop());
                }
                if (ops.isEmpty()) throw new RuntimeException("Mismatched parentheses");
                ops.pop(); // remove '('
            } else if (c == '+' || c == '-' || c == '*') {
                while (!ops.isEmpty() && precedence(ops.peek()) >= precedence(c)) {
                    output.append(ops.pop());
                }
                ops.push(c);
            } else {
                throw new RuntimeException("Invalid character: " + c);
            }
        }
        while (!ops.isEmpty()) {
            char op = ops.pop();
            if (op == '(') throw new RuntimeException("Mismatched parentheses");
            output.append(op);
        }
        return output.toString();
    }

    static int precedence(char op) {
        if (op == '+' || op == '-') return 1;
        if (op == '*') return 2;
        return 0;
    }

    static int evalPostfix(String postfix) {
        Stack<Integer> stack = new Stack<>();
        for (char c : postfix.toCharArray()) {
            if (c == '0' || c == '1') {
                stack.push(c - '0');
            } else {
                if (stack.size() < 2) throw new RuntimeException("Invalid expression");
                int b = stack.pop();
                int a = stack.pop();
                switch (c) {
                    case '+': stack.push(a + b); break;
                    case '-': stack.push(a - b); break;
                    case '*': stack.push(a * b); break;
                    default: throw new RuntimeException("Unknown operator");
                }
            }
        }
        if (stack.size() != 1) throw new RuntimeException("Invalid expression");
        return stack.pop();
    }
}

