import java.util.*;

/*
We count the number of valid original equations for an encrypted string.

Original equation characters are from:
  digits: 0,1
  ops: +,-,*
  parens: ( )
  equal: =

Encryption rule:
- Some occurrences of an original character may be replaced by a letter.
- For a fixed original character, all replaced occurrences use the same letter.
- Two different original characters never use the same letter.
Thus each letter, if used, stands for exactly one original character.
A character occurrence in the encrypted string is either:
- an original symbol itself, fixed;
- or a letter, which must decode consistently to one original symbol.

We must count how many decodings produce a syntactically valid equation with exactly one '='
and both sides evaluate equally, according to grammar over binary numbers.

Grammar used:
Equation := Expr '=' Expr
Expr     := Term ((+|-) Term)*
Term     := Factor ('*' Factor)*
Factor   := Number | '(' Expr ')'
Number   := Binary numeral over {0,1}, interpreted in base 2
We assume usual no-leading-zero restriction except single digit "0":
  Number := "0" | "1" ("0"|"1")*
This is the standard interpretation to avoid ambiguity in tokenization.
Without this, parsing would be highly ambiguous.

Approach:
- Let letters appearing in the encrypted string be variables.
- Each variable maps injectively to one of 8 original symbols.
- Fixed non-letter symbols constrain positions directly.
- We DFS over letter->symbol assignments with pruning from positions:
    if a letter occurs where only some symbols are possible due to fixed chars, restrict domain.
- For each complete assignment, decode the whole string into symbols and test:
    * exactly one '='
    * parse left and right using recursive descent
    * evaluate using BigInteger
    * compare equality
- Count valid assignments.

Because at most 26 letters but only 8 target symbols, only letters that appear matter and
at most 8 distinct letters can be assigned; if more than 8 distinct letters occur answer is 0.
*/

public class Main {
    static final char[] SYMBOLS = {'0', '1', '+', '-', '*', '(', ')', '='};
    static final int SYM_CNT = 8;

    static String s;
    static int n;

    static ArrayList<Character> lettersList = new ArrayList<>();
    static Map<Character, Integer> letterIndex = new HashMap<>();
    static int L;

    static int[] assign;          // letter idx -> symbol idx, -1 unassigned
    static boolean[] usedSymbol;  // symbol idx used by some letter

    static ArrayList<Integer>[] positionsOfLetter;
    static long answer = 0;

    static int[] domainMask; // possible symbols per letter from fixed-position constraints

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        s = fs.next();
        if (s == null) return;
        n = s.length();

        collectLetters();
        if (L > SYM_CNT) {
            System.out.println(0);
            return;
        }

        positionsOfLetter = new ArrayList[L];
        for (int i = 0; i < L; i++) positionsOfLetter[i] = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (isLetter(c)) {
                int idx = letterIndex.get(c);
                positionsOfLetter[idx].add(i);
            } else if (!isSymbol(c)) {
                System.out.println(0);
                return;
            }
        }

        domainMask = new int[L];
        Arrays.fill(domainMask, (1 << SYM_CNT) - 1);

        // Basic positional constraints from fixed characters around? None directly from neighbors.
        // But if a letter appears where the encrypted char itself is a letter, any symbol is possible.
        // Additional direct constraints do not exist.
        // However, if same letter also appears as fixed symbol somewhere impossible - not applicable.

        assign = new int[L];
        Arrays.fill(assign, -1);
        usedSymbol = new boolean[SYM_CNT];

        Integer[] order = new Integer[L];
        for (int i = 0; i < L; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> {
            int ca = Integer.bitCount(domainMask[a]);
            int cb = Integer.bitCount(domainMask[b]);
            if (ca != cb) return Integer.compare(ca, cb);
            return Integer.compare(positionsOfLetter[b].size(), positionsOfLetter[a].size());
        });

        dfs(0, order);
        System.out.println(answer);
    }

    static void dfs(int at, Integer[] order) {
        if (at == L) {
            if (checkCurrentAssignment()) answer++;
            return;
        }
        int li = order[at];
        int mask = domainMask[li];
        for (int si = 0; si < SYM_CNT; si++) {
            if (((mask >> si) & 1) == 0) continue;
            if (usedSymbol[si]) continue;
            assign[li] = si;
            usedSymbol[si] = true;
            dfs(at + 1, order);
            usedSymbol[si] = false;
            assign[li] = -1;
        }
    }

    static boolean checkCurrentAssignment() {
        char[] dec = new char[n];
        int eqCount = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (isLetter(c)) {
                int li = letterIndex.get(c);
                dec[i] = SYMBOLS[assign[li]];
            } else {
                dec[i] = c;
            }
            if (!isSymbol(dec[i])) return false;
            if (dec[i] == '=') eqCount++;
        }
        if (eqCount != 1) return false;

        int eqPos = -1;
        for (int i = 0; i < n; i++) if (dec[i] == '=') { eqPos = i; break; }
        if (eqPos <= 0 || eqPos >= n - 1) return false;

        Parser left = new Parser(dec, 0, eqPos);
        java.math.BigInteger lv = left.parseExpr();
        if (lv == null || left.pos != eqPos) return false;

        Parser right = new Parser(dec, eqPos + 1, n);
        java.math.BigInteger rv = right.parseExpr();
        if (rv == null || right.pos != n) return false;

        return lv.equals(rv);
    }

    static class Parser {
        char[] a;
        int pos, end;

        Parser(char[] a, int l, int r) {
            this.a = a;
            this.pos = l;
            this.end = r;
        }

        java.math.BigInteger parseExpr() {
            java.math.BigInteger val = parseTerm();
            if (val == null) return null;
            while (pos < end && (a[pos] == '+' || a[pos] == '-')) {
                char op = a[pos++];
                java.math.BigInteger t = parseTerm();
                if (t == null) return null;
                if (op == '+') val = val.add(t);
                else val = val.subtract(t);
            }
            return val;
        }

        java.math.BigInteger parseTerm() {
            java.math.BigInteger val = parseFactor();
            if (val == null) return null;
            while (pos < end && a[pos] == '*') {
                pos++;
                java.math.BigInteger f = parseFactor();
                if (f == null) return null;
                val = val.multiply(f);
            }
            return val;
        }

        java.math.BigInteger parseFactor() {
            if (pos >= end) return null;
            if (a[pos] == '(') {
                pos++;
                java.math.BigInteger v = parseExpr();
                if (v == null) return null;
                if (pos >= end || a[pos] != ')') return null;
                pos++;
                return v;
            }
            return parseNumber();
        }

        java.math.BigInteger parseNumber() {
            if (pos >= end) return null;
            if (a[pos] != '0' && a[pos] != '1') return null;

            if (a[pos] == '0') {
                pos++;
                // no leading zeros: next char cannot be digit continuing same number
                if (pos < end && (a[pos] == '0' || a[pos] == '1')) return null;
                return java.math.BigInteger.ZERO;
            } else {
                int start = pos;
                pos++;
                while (pos < end && (a[pos] == '0' || a[pos] == '1')) pos++;
                java.math.BigInteger v = java.math.BigInteger.ZERO;
                for (int i = start; i < pos; i++) {
                    v = v.shiftLeft(1);
                    if (a[i] == '1') v = v.add(java.math.BigInteger.ONE);
                }
                return v;
            }
        }
    }

    static void collectLetters() {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (isLetter(c) && !letterIndex.containsKey(c)) {
                letterIndex.put(c, lettersList.size());
                lettersList.add(c);
            }
        }
        L = lettersList.size();
    }

    static boolean isLetter(char c) {
        return ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z');
    }

    static boolean isSymbol(char c) {
        return c == '0' || c == '1' || c == '+' || c == '-' || c == '*' || c == '(' || c == ')' || c == '=';
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= 32);
            while (c > 32) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

#define MAX_LEN 55
#define MOD 1000000007

char s[MAX_LEN];
int n;
int mapping[256]; // mapping from character to digit (0-9) or -1 if not mapped
int used[10];
long long ans;
int left_eq, right_eq; // positions of '='

// Structure to hold expression parse result
typedef struct {
    long long val; // value of expression (binary)
    int ok;        // 1 if valid, 0 otherwise
} ExprResult;

// Evaluate expression from l to r (inclusive) with given mapping
ExprResult eval_expr(int l, int r);

// Find matching parenthesis
int match_paren(int l) {
    int cnt = 1;
    for (int i = l + 1; i < n; i++) {
        if (s[i] == '(') cnt++;
        else if (s[i] == ')') cnt--;
        if (cnt == 0) return i;
    }
    return -1;
}

// Evaluate a number substring
ExprResult eval_num(int l, int r) {
    ExprResult res = {0, 1};
    if (l > r) { res.ok = 0; return res; }
    // Check for leading zero
    if (s[l] == '0' && l < r) { res.ok = 0; return res; }
    long long val = 0;
    for (int i = l; i <= r; i++) {
        char c = s[i];
        int d;
        if (c >= '0' && c <= '9') {
            d = c - '0';
        } else if (c >= 'A' && c <= 'Z') {
            d = mapping[(int)c];
            if (d == -1) { res.ok = 0; return res; }
        } else {
            res.ok = 0; return res;
        }
        val = val * 2 + d;
        if (val > 1e15) { res.ok = 0; return res; } // overflow guard
    }
    res.val = val;
    return res;
}

// Evaluate term: factor (* factor)*
ExprResult eval_term(int l, int r) {
    ExprResult res = {1, 1};
    int i = l;
    while (i <= r) {
        ExprResult factor;
        if (s[i] == '(') {
            int j = match_paren(i);
            if (j == -1 || j > r) { res.ok = 0; return res; }
            factor = eval_expr(i+1, j-1);
            i = j + 1;
        } else {
            int start = i;
            while (i <= r && (isdigit(s[i]) || (s[i] >= 'A' && s[i] <= 'Z'))) i++;
            factor = eval_num(start, i-1);
        }
        if (!factor.ok) { res.ok = 0; return res; }
        if (i <= r && s[i] == '*') {
            res.val *= factor.val;
            if (res.val > 1e15) { res.ok = 0; return res; }
            i++; // skip '*'
        } else {
            res.val *= factor.val;
            if (res.val > 1e15) { res.ok = 0; return res; }
            break;
        }
    }
    return res;
}

// Evaluate expression: term ((+/-) term)*
ExprResult eval_expr(int l, int r) {
    ExprResult res = {0, 1};
    int op = '+'; // first operator is '+'
    int i = l;
    while (i <= r) {
        ExprResult term;
        if (s[i] == '(') {
            int j = match_paren(i);
            if (j == -1 || j > r) { res.ok = 0; return res; }
            term = eval_expr(i+1, j-1);
            i = j + 1;
        } else {
            int start = i;
            while (i <= r && (isdigit(s[i]) || (s[i] >= 'A' && s[i] <= 'Z'))) i++;
            term = eval_num(start, i-1);
        }
        if (!term.ok) { res.ok = 0; return res; }
        if (op == '+') res.val += term.val;
        else if (op == '-') res.val -= term.val;
        if (res.val < 0 || res.val > 1e15) { res.ok = 0; return res; }
        if (i <= r && (s[i] == '+' || s[i] == '-')) {
            op = s[i];
            i++;
        } else {
            break;
        }
    }
    return res;
}

// Check if whole equation is valid
int check_equation() {
    // Find '='
    int eq_pos = -1;
    for (int i = 0; i < n; i++) {
        if (s[i] == '=') { eq_pos = i; break; }
    }
    if (eq_pos == -1) return 0;
    ExprResult left = eval_expr(0, eq_pos-1);
    ExprResult right = eval_expr(eq_pos+1, n-1);
    if (!left.ok || !right.ok) return 0;
    return (left.val == right.val);
}

// Count distinct letters in the encrypted string
int count_letters() {
    int cnt = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] >= 'A' && s[i] <= 'Z') cnt++;
    }
    return cnt;
}

// Recursive backtracking to assign digits to letters
void backtrack(int pos) {
    if (pos == n) {
        if (check_equation()) ans++;
        return;
    }
    // Skip non-letter characters
    if (s[pos] < 'A' || s[pos] > 'Z') {
        backtrack(pos+1);
        return;
    }
    // If already mapped, skip
    if (mapping[(int)s[pos]] != -1) {
        backtrack(pos+1);
        return;
    }
    // Try assign 0-9 to this letter
    for (int d = 0; d <= 9; d++) {
        if (!used[d]) {
            // Check leading zero constraint: first char of a number cannot be '0' unless number is single digit
            // We'll handle that in eval_num, but also prune here
            // Quick check: if this letter is at start of a number and d==0, and the number has length >1
            int is_first = 1;
            if (pos > 0 && (isdigit(s[pos-1]) || (s[pos-1] >= 'A' && s[pos-1] <= 'Z'))) is_first = 0;
            if (d == 0 && is_first) {
                // check if this number has more digits
                int len = 0;
                int i = pos;
                while (i < n && (isdigit(s[i]) || (s[i] >= 'A' && s[i] <= 'Z'))) { len++; i++; }
                if (len > 1) continue; // leading zero not allowed
            }
            used[d] = 1;
            mapping[(int)s[pos]] = d;
            backtrack(pos+1);
            mapping[(int)s[pos]] = -1;
            used[d] = 0;
        }
    }
}

int main() {
    // Read input
    if (!fgets(s, MAX_LEN, stdin)) return 1;
    // Remove newline
    int len = strlen(s);
    if (len > 0 && s[len-1] == '\n') s[len-1] = '\0';
    n = strlen(s);

    // Initialize mapping
    for (int i = 0; i < 256; i++) mapping[i] = -1;
    memset(used, 0, sizeof(used));
    ans = 0;

    // Count distinct letters
    int letter_count[26] = {0};
    for (int i = 0; i < n; i++) {
        if (s[i] >= 'A' && s[i] <= 'Z') letter_count[s[i]-'A'] = 1;
    }
    int distinct = 0;
    for (int i = 0; i < 26; i++) if (letter_count[i]) distinct++;

    // If more than 10 distinct letters, answer is 0
    if (distinct > 10) {
        printf("0\n");
        return 0;
    }

    backtrack(0);
    printf("%lld\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAXN 256
#define MAXMASK 1024
#define INF 1000000000

/*
Grammar:
Equation := Expr '=' Expr
Expr     := Term { ('+'|'-') Term }*
Term     := Factor { '*' Factor }*
Factor   := BinaryNumber | '(' Expr ')'
BinaryNumber := [01]+

Encrypted string contains:
- fixed symbols among 0,1,+,-,*,(,),=
- letters, each letter consistently stands for exactly one original character
- different original characters map to different letters
We count number of distinct original equations consistent with encryption and grammar/value equality.

Observation:
There are only 8 possible original characters:
0 1 + - * ( ) =

Each distinct letter must be assigned injectively to one of these 8 chars,
also respecting all fixed positions:
- if s[i] is fixed char c => original char at i is c
- if s[i] is letter x => original char at i is assigned char map[x]

Thus every assignment yields a fully determined candidate string over 8 chars.
Need count those that are syntactically valid equation and evaluate equal.

Number of distinct letters <= 8, otherwise impossible.
Bruteforce injective assignments with pruning by availability.
For each complete assignment, build string and parse/evaluate.

Expression values are binary integers. We use unsigned long long with overflow check capped.
To stay safe, reject values exceeding LIMIT during parse; grammar only needs equality, but
problem statement gives no bounds. We use arbitrary-ish cap via __int128 and prune if too large.
Since input size likely modest and binary numbers/operators only, this is acceptable.
*/

typedef unsigned long long ULL;
const __int128 LIMIT = (((__int128)1) << 120); /* huge practical cap */

char s[MAXN];
int n;

int letter_id[256];
char letters[16];
int L;

char origChars[8] = {'0','1','+','-','*','(',')','='};

typedef struct {
    int ok;
    __int128 val;
} Res;

typedef struct {
    const char *t;
    int len;
    int pos;
} Parser;

static int is_bin_digit(char c) { return c=='0' || c=='1'; }

static Res make_fail() {
    Res r; r.ok = 0; r.val = 0; return r;
}
static Res make_ok(__int128 v) {
    Res r; r.ok = 1; r.val = v; return r;
}

static Res parseExpr(Parser *p);

static Res parseNumber(Parser *p) {
    if (p->pos >= p->len || !is_bin_digit(p->t[p->pos])) return make_fail();
    __int128 v = 0;
    while (p->pos < p->len && is_bin_digit(p->t[p->pos])) {
        v = v * 2 + (p->t[p->pos] - '0');
        if (v > LIMIT) return make_fail();
        p->pos++;
    }
    return make_ok(v);
}

static Res parseFactor(Parser *p) {
    if (p->pos >= p->len) return make_fail();
    if (p->t[p->pos] == '(') {
        p->pos++;
        Res r = parseExpr(p);
        if (!r.ok) return r;
        if (p->pos >= p->len || p->t[p->pos] != ')') return make_fail();
        p->pos++;
        return r;
    }
    return parseNumber(p);
}

static Res parseTerm(Parser *p) {
    Res left = parseFactor(p);
    if (!left.ok) return left;
    while (p->pos < p->len && p->t[p->pos] == '*') {
        p->pos++;
        Res right = parseFactor(p);
        if (!right.ok) return right;
        __int128 v = left.val * right.val;
        if (v > LIMIT) return make_fail();
        left.val = v;
    }
    return left;
}

static Res parseExpr(Parser *p) {
    Res left = parseTerm(p);
    if (!left.ok) return left;
    while (p->pos < p->len && (p->t[p->pos] == '+' || p->t[p->pos] == '-')) {
        char op = p->t[p->pos++];
        Res right = parseTerm(p);
        if (!right.ok) return right;
        __int128 v = (op == '+') ? (left.val + right.val) : (left.val - right.val);
        if (v < -LIMIT || v > LIMIT) return make_fail();
        left.val = v;
    }
    return left;
}

static int validate_equation(const char *t, int len) {
    int eq = -1, cnt = 0;
    for (int i = 0; i < len; i++) {
        if (t[i] == '=') { eq = i; cnt++; }
    }
    if (cnt != 1) return 0;
    if (eq == 0 || eq == len - 1) return 0;

    Parser p1 = { t, eq, 0 };
    Res a = parseExpr(&p1);
    if (!a.ok || p1.pos != eq) return 0;

    Parser p2 = { t + eq + 1, len - eq - 1, 0 };
    Res b = parseExpr(&p2);
    if (!b.ok || p2.pos != len - eq - 1) return 0;

    return a.val == b.val;
}

