#include <bits/stdc++.h>
using namespace std;

string s;
vector<char> letters;
map<char, char> mapping;
set<char> used_chars;
int ans = 0;

bool is_digit(char c) { return c == '0' || c == '1'; }

bool is_operator(char c) { return c == '+' || c == '-' || c == '*'; }

// Parse and evaluate binary expression (no overflow issues)
int parse_expr(const string &expr, int &i);
int parse_term(const string &expr, int &i);
int parse_factor(const string &expr, int &i);

int parse_factor(const string &expr, int &i) {
    if (expr[i] == '(') {
        i++; // '('
        int val = parse_expr(expr, i);
        i++; // ')'
        return val;
    }
    // must be binary number
    string num;
    while (i < (int)expr.size() && is_digit(expr[i])) {
        num += expr[i];
        i++;
    }
    if (num.empty()) return -1; // invalid
    // Convert binary string to int
    int val = 0;
    for (char c : num) {
        val = val * 2 + (c - '0');
    }
    return val;
}

int parse_term(const string &expr, int &i) {
    int val = parse_factor(expr, i);
    while (i < (int)expr.size() && expr[i] == '*') {
        i++; // '*'
        int rhs = parse_factor(expr, i);
        val *= rhs;
    }
    return val;
}

int parse_expr(const string &expr, int &i) {
    int val = parse_term(expr, i);
    while (i < (int)expr.size() && (expr[i] == '+' || expr[i] == '-')) {
        char op = expr[i];
        i++;
        int rhs = parse_term(expr, i);
        if (op == '+') val += rhs;
        else val -= rhs;
    }
    return val;
}

int evaluate(const string &side) {
    int i = 0;
    int val = parse_expr(side, i);
    return val;
}

bool is_valid_expression(const string &expr) {
    if (expr.empty()) return false;
    // Check balanced parentheses and valid characters
    int bal = 0;
    for (char c : expr) {
        if (c == '(') bal++;
        else if (c == ')') bal--;
        if (bal < 0) return false;
        if (!is_digit(c) && !is_operator(c) && c != '(' && c != ')') return false;
    }
    if (bal != 0) return false;
    // Check operator/digit placement
    for (int i = 0; i < (int)expr.size(); i++) {
        if (is_operator(expr[i])) {
            if (i == 0 || i == (int)expr.size()-1) return false;
            if (is_operator(expr[i-1]) || expr[i-1] == '(') return false;
            if (is_operator(expr[i+1]) || expr[i+1] == ')') return false;
        }
        if (expr[i] == '(') {
            if (i+1 < (int)expr.size() && is_operator(expr[i+1])) return false;
        }
        if (expr[i] == ')') {
            if (i > 0 && is_operator(expr[i-1])) return false;
        }
        // Digits: only 0 or 1 allowed
        if (isdigit(expr[i]) && expr[i] != '0' && expr[i] != '1') return false;
    }
    return true;
}

bool is_valid_equation(const string &eq) {
    int eq_pos = -1;
    for (int i = 0; i < (int)eq.size(); i++) {
        if (eq[i] == '=') {
            if (eq_pos != -1) return false; // more than one '='
            eq_pos = i;
        }
    }
    if (eq_pos == -1 || eq_pos == 0 || eq_pos == (int)eq.size()-1) return false;
    string left = eq.substr(0, eq_pos);
    string right = eq.substr(eq_pos+1);
    if (!is_valid_expression(left) || !is_valid_expression(right)) return false;
    int lval = evaluate(left);
    int rval = evaluate(right);
    return lval == rval;
}

void backtrack(int idx) {
    if (idx == (int)letters.size()) {
        // Build candidate equation
        string cand = s;
        for (int i = 0; i < (int)cand.size(); i++) {
            if (isalpha(cand[i])) {
                cand[i] = mapping[cand[i]];
            }
        }
        if (is_valid_equation(cand)) {
            ans++;
        }
        return;
    }
    char letter = letters[idx];
    // Possible original chars: '0','1','+','-','*','(',')','='
    string possible = "01+-*()=";
    for (char c : possible) {
        if (used_chars.count(c)) continue;
        // '=' must appear exactly once in the original: we can allow multiple mapping to '=' only if it appears once in s
        // But we must enforce that exactly one '=' in final equation. We'll check at end.
        mapping[letter] = c;
        used_chars.insert(c);
        backtrack(idx+1);
        used_chars.erase(c);
    }
}

