    set<char> letter_set;
    for (char c : s) {
        if (isalpha(c)) letter_set.insert(c);
    }
    letters.assign(letter_set.begin(), letter_set.end());

    backtrack(0);
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

struct Parser {
    string s;
    int n;
    int pos;
    bool ok;

    Parser(const string& str) : s(str), n((int)str.size()), pos(0), ok(true) {}

    // Grammar:
    // equation := expr '=' expr
    // expr     := term { ('+'|'-') term }
    // term     := factor { '*' factor }
    // factor   := binary_number | '(' expr ')'
    // binary_number := [01]+
    //
    // All operators are left-associative with usual precedence.

    i128 parseEquation() {
        i128 left = parseExpr();
        if (!ok) return 0;
        if (pos >= n || s[pos] != '=') { ok = false; return 0; }
        ++pos;
        i128 right = parseExpr();
        if (!ok) return 0;
        if (pos != n) { ok = false; return 0; }
        return (left == right) ? 1 : 0;
    }

    i128 parseExpr() {
        i128 v = parseTerm();
        if (!ok) return 0;
        while (pos < n && (s[pos] == '+' || s[pos] == '-')) {
            char op = s[pos++];
            i128 t = parseTerm();
            if (!ok) return 0;
            if (op == '+') v += t;
            else v -= t;
        }
        return v;
    }

    i128 parseTerm() {
        i128 v = parseFactor();
        if (!ok) return 0;
        while (pos < n && s[pos] == '*') {
            ++pos;
            i128 t = parseFactor();
            if (!ok) return 0;
            v *= t;
        }
        return v;
    }

    i128 parseFactor() {
        if (pos >= n) { ok = false; return 0; }
        if (s[pos] == '(') {
            ++pos;
            i128 v = parseExpr();
            if (!ok) return 0;
            if (pos >= n || s[pos] != ')') { ok = false; return 0; }
            ++pos;
            return v;
        } else {
            return parseBinary();
        }
    }

    i128 parseBinary() {
        if (pos >= n || (s[pos] != '0' && s[pos] != '1')) {
            ok = false;
            return 0;
        }
        i128 v = 0;
        while (pos < n && (s[pos] == '0' || s[pos] == '1')) {
            v = v * 2 + (s[pos] - '0');
            ++pos;
        }
        return v;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string enc;
    if (!(cin >> enc)) return 0;

    // Characters that may appear in original equation:
    // 0,1,+,-,*,(,),=
    const string base = "01+-*()=";
    const int K = 8;

    vector<char> letters;
    vector<int> seen(256, 0);
    for (char c : enc) {
        if (base.find(c) == string::npos && !seen[(unsigned char)c]) {
            seen[(unsigned char)c] = 1;
            letters.push_back(c);
        }
    }

    int m = (int)letters.size();
    if (m > K) {
        cout << 0 << '\n';
        return 0;
    }

    unordered_map<char, int> id;
    for (int i = 0; i < m; ++i) id[letters[i]] = i;

    long long ans = 0;
    vector<int> perm(K);
    iota(perm.begin(), perm.end(), 0);

    // Injective mapping from letters to base characters.
    // For each mapping, construct the candidate original equation and validate.
    do {
        string cand = enc;
        for (char &c : cand) {
            auto it = id.find(c);
            if (it != id.end()) c = base[perm[it->second]];
        }

        Parser p(cand);
        if (p.parseEquation() == 1 && p.ok) ++ans;

    } while (next_permutation(perm.begin(), perm.end()));

    // Each permutation of 8 items assigns first m images to letters.
    // Since we only care about first m positions, each injective mapping is counted (8-m)! times.
    for (int x = 2; x <= K - m; ++x) ans /= x;

    cout << ans << '\n';
    return 0;
}

import sys
from itertools import permutations

def evaluate_expression(expr):
    """Evaluates a simple expression with +, -, * and parentheses.
    Returns the integer result or raises an exception on invalid input."""
    # We'll use Python's eval but restrict to safe operations.
    # Since we control input after substitution, it's safe here.
    return eval(expr, {"__builtins__": {}}, {})

def is_valid_equation(s):
    """Check if the string is a valid arithmetic equation with = sign."""
    if '=' not in s:
        return False
    left, right = s.split('=', 1)
    if not left or not right:
        return False
    try:
        return evaluate_expression(left) == evaluate_expression(right)
    except:
        return False

def has_leading_zero(num_str):
    """Return True if the number string has a leading zero and length > 1."""
    return len(num_str) > 1 and num_str[0] == '0'

def contains_leading_zero(expr):
    """Check if any number in expression has leading zero."""
    tokens = []
    current = ''
    for ch in expr:
        if ch.isdigit():
            current += ch
        else:
            if current:
                tokens.append(current)
                current = ''
            tokens.append(ch)
    if current:
        tokens.append(current)
    for token in tokens:
        if token.isdigit() and has_leading_zero(token):
            return True
    return False

def solve():
    encrypted = sys.stdin.readline().strip()
    letters = sorted(set(ch for ch in encrypted if ch.isalpha()))
    count = 0

    if not letters:
        # No letters, just check if the equation itself is valid
        if is_valid_equation(encrypted) and not contains_leading_zero(encrypted):
            count = 1
        print(count)
        return

    # Try all assignments of digits to letters
    for perm in permutations('0123456789', len(letters)):
        trans = str.maketrans(''.join(letters), ''.join(perm))
        candidate = encrypted.translate(trans)
        if contains_leading_zero(candidate):
            continue
        if is_valid_equation(candidate):
            count += 1

    print(count)

if __name__ == "__main__":
    solve()
